// Sweep harness: times many GEMM kernel configurations on the A40.
// Instantiated as templates; driver picks grid dims. Reports TFLOP/s.
#include <cuda_runtime.h>
#include <cuda_pipeline.h>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>

// ---------------------------------------------------------------------------
// Register-staging double-buffer kernel (prefetch through registers into a
// second shared buffer, then compute from the first -> overlap global loads
// with compute). A scalar reads (odd/mod4 conflict-free), B float4 reads.
// ---------------------------------------------------------------------------
template <int BM, int BN, int BK, int THREADS, int STAGES>
__global__ void __launch_bounds__(THREADS)
kernelReg(const float* __restrict__ A, const float* __restrict__ B,
          float* __restrict__ C, int N) {
    const int AS = BK + 4;          // A stride (mod-4, conflict-free scalar)
    const int BS = BN;              // B stride (16-aligned)
    __shared__ float As[STAGES][BM][AS];
    __shared__ float Bs[STAGES][BK][BS];

    const int tid  = threadIdx.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int WR = BM / 64, WC = BN / 32;
    const int warpR = warp / WC, warpC = warp % WC;
    const int ty = lane >> 2, tx = lane & 3;
    const int rLo = warpR * 64 + ty * 8;
    const int cLo = warpC * 32 + tx * 8;
    const int row0 = blockIdx.y * BM, col0 = blockIdx.x * BN;
    const int nKT = (N + BK - 1) / BK;

    float acc[8][8];
#pragma unroll
    for (int i = 0; i < 8; ++i)
#pragma unroll
        for (int j = 0; j < 8; ++j) acc[i][j] = 0.f;

    auto loadStage = [&](int k0, int slot) {
        // A
#pragma unroll
        for (int i = 0; i < (BM * BK + THREADS - 1) / THREADS; ++i) {
            int idx = tid + i * THREADS;
            if (idx < BM * BK) {
                int r = idx / BK, k = idx % BK;
                int gr = row0 + r, gc = k0 + k;
                As[slot][r][k] = (gr < N && gc < N) ? A[gr * N + gc] : 0.f;
            }
        }
        // B float4
#pragma unroll
        for (int i = 0; i < (BK * BN / 4 + THREADS - 1) / THREADS; ++i) {
            int idx = tid + i * THREADS;
            if (idx < BK * BN / 4) {
                int k = idx / (BN / 4), cf = idx % (BN / 4);
                int gr = k0 + k, gc = col0 + (cf << 2);
                float4 v;
                if (gr < N && gc + 3 < N) v = *reinterpret_cast<const float4*>(&B[gr * N + gc]);
                else {
                    v.x = (gr < N && gc + 0 < N) ? B[gr * N + gc + 0] : 0.f;
                    v.y = (gr < N && gc + 1 < N) ? B[gr * N + gc + 1] : 0.f;
                    v.z = (gr < N && gc + 2 < N) ? B[gr * N + gc + 2] : 0.f;
                    v.w = (gr < N && gc + 3 < N) ? B[gr * N + gc + 3] : 0.f;
                }
                Bs[slot][k][cf << 2] = v.x; Bs[slot][k][cf << 2 | 1] = v.y;
                Bs[slot][k][cf << 2 | 2] = v.z; Bs[slot][k][cf << 2 | 3] = v.w;
            }
        }
    };

    loadStage(0, 0);
    __syncthreads();
    for (int t = 0; t < nKT; ++t) {
        int slot = t % 2;
        int nslot = slot ^ 1;
        if (t + 1 < nKT) loadStage((t + 1) * BK, nslot);
#pragma unroll
        for (int k = 0; k < BK; ++k) {
            float av[8];
#pragma unroll
            for (int i = 0; i < 8; ++i) av[i] = As[slot][rLo + i][k];
            float4 b0 = *reinterpret_cast<const float4*>(&Bs[slot][k][cLo]);
            float4 b1 = *reinterpret_cast<const float4*>(&Bs[slot][k][cLo + 4]);
            float bv[8] = {b0.x,b0.y,b0.z,b0.w,b1.x,b1.y,b1.z,b1.w};
#pragma unroll
            for (int i = 0; i < 8; ++i)
#pragma unroll
                for (int j = 0; j < 8; ++j) acc[i][j] += av[i] * bv[j];
        }
        __syncthreads();
    }
    int gR0 = row0 + rLo, gC0 = col0 + cLo;
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        int r = gR0 + i; if (r >= N) continue;
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            int c = gC0 + j; if (c < N) C[r * N + c] = acc[i][j];
        }
    }
}

// ---------------------------------------------------------------------------
// cp.async multi-stage kernel.
// ---------------------------------------------------------------------------
template <int BM, int BN, int BK, int THREADS, int STAGES>
__global__ void __launch_bounds__(THREADS)
kernelAsync(const float* __restrict__ A, const float* __restrict__ B,
            float* __restrict__ C, int N) {
    const int AS = BK + 4;
    const int BS = BN;
    __shared__ float As[STAGES][BM][AS];
    __shared__ float Bs[STAGES][BK][BS];

    const int tid  = threadIdx.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int WR = BM / 64, WC = BN / 32;
    const int warpR = warp / WC, warpC = warp % WC;
    const int ty = lane >> 2, tx = lane & 3;
    const int rLo = warpR * 64 + ty * 8;
    const int cLo = warpC * 32 + tx * 8;
    const int row0 = blockIdx.y * BM, col0 = blockIdx.x * BN;
    const int nKT = (N + BK - 1) / BK;

    float acc[8][8];
#pragma unroll
    for (int i = 0; i < 8; ++i)
#pragma unroll
        for (int j = 0; j < 8; ++j) acc[i][j] = 0.f;

    auto loadStage = [&](int k0, int slot) {
#pragma unroll
        for (int i = 0; i < (BM * BK + THREADS - 1) / THREADS; ++i) {
            int idx = tid + i * THREADS;
            if (idx < BM * BK) {
                int r = idx / BK, k = idx % BK;
                int gr = row0 + r, gc = k0 + k;
                if (gr < N && gc < N)
                    __pipeline_memcpy_async(&As[slot][r][k], &A[gr * N + gc], 4);
                else As[slot][r][k] = 0.f;
            }
        }
#pragma unroll
        for (int i = 0; i < (BK * BN / 4 + THREADS - 1) / THREADS; ++i) {
            int idx = tid + i * THREADS;
            if (idx < BK * BN / 4) {
                int k = idx / (BN / 4), cf = idx % (BN / 4);
                int gr = k0 + k, gc = col0 + (cf << 2);
                if (gr < N && gc + 3 < N)
                    __pipeline_memcpy_async(&Bs[slot][k][cf << 2], &B[gr * N + gc], 16);
                else {
                    Bs[slot][k][cf<<2]=(gr<N&&gc<N)?B[gr*N+gc]:0.f;
                    Bs[slot][k][cf<<2|1]=(gr<N&&gc+1<N)?B[gr*N+gc+1]:0.f;
                    Bs[slot][k][cf<<2|2]=(gr<N&&gc+2<N)?B[gr*N+gc+2]:0.f;
                    Bs[slot][k][cf<<2|3]=(gr<N&&gc+3<N)?B[gr*N+gc+3]:0.f;
                }
            }
        }
    };

    int issued = 0;
    while (issued < nKT && issued < STAGES - 1) { loadStage(issued * BK, issued % STAGES); __pipeline_commit(); ++issued; }
    for (int t = 0; t < nKT; ++t) {
        __pipeline_wait_prior((issued - 1) - t);
        __syncthreads();
        if (issued < nKT) { loadStage(issued * BK, issued % STAGES); __pipeline_commit(); ++issued; }
        int slot = t % STAGES;
#pragma unroll
        for (int k = 0; k < BK; ++k) {
            float av[8];
#pragma unroll
            for (int i = 0; i < 8; ++i) av[i] = As[slot][rLo + i][k];
            float4 b0 = *reinterpret_cast<const float4*>(&Bs[slot][k][cLo]);
            float4 b1 = *reinterpret_cast<const float4*>(&Bs[slot][k][cLo + 4]);
            float bv[8] = {b0.x,b0.y,b0.z,b0.w,b1.x,b1.y,b1.z,b1.w};
#pragma unroll
            for (int i = 0; i < 8; ++i)
#pragma unroll
                for (int j = 0; j < 8; ++j) acc[i][j] += av[i] * bv[j];
        }
        __syncthreads();
    }
    int gR0 = row0 + rLo, gC0 = col0 + cLo;
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        int r = gR0 + i; if (r >= N) continue;
#pragma unroll
        for (int j = 0; j < 8; ++j) { int c = gC0 + j; if (c < N) C[r * N + c] = acc[i][j]; }
    }
}

// ---- host driver ----
template <int BM,int BN,int BK,int THREADS,int STAGES,int MODE>
double run(const float* A,const float* B,float* C,int N,int it){
    dim3 block(THREADS), grid((N+BM-1)/BM,(N+BN-1)/BN);
    auto launch=[&](){
      if(MODE==0) kernelReg<BM,BN,BK,THREADS,STAGES><<<grid,block>>>(A,B,C,N);
      else kernelAsync<BM,BN,BK,THREADS,STAGES><<<grid,block>>>(A,B,C,N);
    };
    for(int i=0;i<8;i++)launch(); cudaDeviceSynchronize();
    cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
    cudaEventRecord(a);
    for(int i=0;i<it;i++)launch();
    cudaEventRecord(b);cudaEventSynchronize(b);
    float ms;cudaEventElapsedTime(&ms,a,b);
    return 2.0*(double)N*N*N*it/(ms/1e3)/1e12;
}

#define RUN(bm,bn,bk,th,st,md) {double t=run<bm,bn,bk,th,st,md>(A,B,C,N,IT); \
  printf("BM=%d BN=%d BK=%d thr=%d st=%d %-8s %.2f TFLOP/s\n",bm,bn,bk,th,st, \
    md==0?"reg":"async", t); fflush(stdout);}

int main(){
  int N=4096; size_t by=(size_t)N*N*4; int IT=30;
  float *A,*B,*C;cudaMalloc(&A,by);cudaMalloc(&B,by);cudaMalloc(&C,by);
