// Variant "TA": A stored transposed in shared (As[k][row], stride BM) so both
// A and B reads are conflict-free float4. A filled by sync transposing load,
// B by cp.async (natural, row-major cols). cp.async still async for B; A uses
// double-buffered sync prefetch to overlap with compute.
template <int BM,int BN,int BK,int THREADS,int STAGES>
__global__ void __launch_bounds__(THREADS)
kTA(const float* __restrict__ A,const float* __restrict__ B,float* __restrict__ C,int N){
  extern __shared__ float smem[];
  const int AS=BK, BS=BN;
  float (*As)[BK][BM] = reinterpret_cast<float(*)[BK][BM]>(smem);
  float (*Bs)[BK][BS] = reinterpret_cast<float(*)[BK][BS]>(smem + STAGES*BK*BM);

  const int tid=threadIdx.x, warp=tid>>5, lane=tid&31;
  const int ty=lane>>2, tx=lane&3;         // 8x4 within warp
  const int warpR=warp>>2, warpC=warp&3;   // 2x4 warp grid
  const int rLo=warpR*64 + ty*8;
  const int cLo=warpC*32 + tx*8;
  const int row0=blockIdx.y*BM, col0=blockIdx.x*BN;
  const int nKT=(N+BK-1)/BK;

  float acc[8][8];
#pragma unroll
  for(int i=0;i<8;i++)
#pragma unroll
    for(int j=0;j<8;j++) acc[i][j]=0.f;

  auto loadA = [&](int k0,int slot){
    // sync transposing fill (global float4 over k -> 4 transposed stores)
#pragma unroll
    for(int i=0;i<(BM*BK/4+THREADS-1)/THREADS;i++){
      int idx=tid+i*THREADS; if(idx>=BM*BK/4) continue;
      int r=idx/(BK/4), kf=idx%(BK/4);
      int gr=row0+r, gc=k0+kf*4;
      float4 v;
      if(gr<N && gc+3<N) v=*reinterpret_cast<const float4*>(&A[gr*N+gc]);
      else { v.x=gc<N&&gr<N?A[gr*N+gc]:0.f; v.y=gc+1<N&&gr<N?A[gr*N+gc+1]:0.f;
             v.z=gc+2<N&&gr<N?A[gr*N+gc+2]:0.f; v.w=gc+3<N&&gr<N?A[gr*N+gc+3]:0.f; }
      As[slot][kf*4+0][r]=v.x; As[slot][kf*4+1][r]=v.y;
      As[slot][kf*4+2][r]=v.z; As[slot][kf*4+3][r]=v.w;
    }
  };
  auto loadB = [&](int k0,int slot){
#pragma unroll
    for(int i=0;i<(BK*BN/4+THREADS-1)/THREADS;i++){
      int idx=tid+i*THREADS; if(idx>=BK*BN/4) continue;
      int k=idx/(BN/4), cf=idx%(BN/4);
      int gr=k0+k, gc=col0+cf*4;
      if(gr<N && gc+3<N) __pipeline_memcpy_async(&Bs[slot][k][cf*4],&B[gr*N+gc],16);
      else { Bs[slot][k][cf*4+0]=gr<N&&gc<N?B[gr*N+gc]:0.f;
             Bs[slot][k][cf*4+1]=gr<N&&gc+1<N?B[gr*N+gc+1]:0.f;
             Bs[slot][k][cf*4+2]=gr<N&&gc+2<N?B[gr*N+gc+2]:0.f;
             Bs[slot][k][cf*4+3]=gr<N&&gc+3<N?B[gr*N+gc+3]:0.f; }
    }
  };

  int issued=0;
  while(issued<nKT && issued<STAGES-1){ loadA(issued*BK,issued%STAGES); loadB(issued*BK,issued%STAGES); __pipeline_commit(); issued++; }
  for(int t=0;t<nKT;t++){
    __pipeline_wait_prior((issued-1)-t);
    __syncthreads();
    if(issued<nKT){ loadA(issued*BK,issued%STAGES); loadB(issued*BK,issued%STAGES); __pipeline_commit(); issued++; }
    int slot=t%STAGES;
#pragma unroll
    for(int k=0;k<BK;k++){
      // A: 8 rows at As[k][rLo..rLo+7] as 2 float4 (rows contiguous)
      float4 a0,*a1; a0=*reinterpret_cast<const float4*>(&As[slot][k][rLo]);
      a1=reinterpret_cast<const float4*>(&As[slot][k][rLo+4]);
      float av[8]={a0.x,a0.y,a0.z,a0.w,a1->x,a1->y,a1->z,a1->w};
      float4 b0=*reinterpret_cast<const float4*>(&Bs[slot][k][cLo]);
      float4 b1=*reinterpret_cast<const float4*>(&Bs[slot][k][cLo+4]);
      float bv[8]={b0.x,b0.y,b0.z,b0.w,b1.x,b1.y,b1.z,b1.w};
#pragma unroll
      for(int i=0;i<8;i++)
#pragma unroll
        for(int j=0;j<8;j++) acc[i][j]+=av[i]*bv[j];
    }
    __syncthreads();
  }
  int gR0=row0+rLo, gC0=col0+cLo;
#pragma unroll
  for(int i=0;i<8;i++){ int r=gR0+i; if(r>=N)continue;
#pragma unroll
    for(int j=0;j<8;j++){ int c=gC0+j; if(c<N) C[r*N+c]=acc[i][j]; } }
}

template <int BM,int BN,int BK,int THREADS,int STAGES>
double runTA(const float*A,const float*B,float*C,int N,int it){
  size_t sh=((size_t)STAGES*BK*BM + (size_t)STAGES*BK*BN)*4;
  dim3 block(THREADS),grid((N+BM-1)/BM,(N+BN-1)/BN);
  cudaFuncSetAttribute(kTA<BM,BN,BK,THREADS,STAGES>,cudaFuncAttributeMaxDynamicSharedMemorySize,(int)sh);
  auto launch=[&](){ kTA<BM,BN,BK,THREADS,STAGES><<<grid,block,sh>>>(A,B,C,N); };
  for(int i=0;i<6;i++)launch(); cudaDeviceSynchronize();
  if(cudaGetLastError()!=cudaSuccess){printf("LAUNCH FAIL sh=%zu %s\n",sh,cudaGetErrorString(cudaGetLastError()));return -1;}
  cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
  cudaEventRecord(a); for(int i=0;i<it;i++)launch(); cudaEventRecord(b);
  cudaEventSynchronize(b); float ms;cudaEventElapsedTime(&ms,a,b);
  return 2.0*N*N*N*it/(ms/1e3)/1e12;
}

int main(){
  int N=4096; size_t by=(size_t)N*N*4; int IT=30;
  float*A,*B,*C;cudaMalloc(&A,by);cudaMalloc(&B,by);cudaMalloc(&C,by);
  for(size_t i=0;i<by/4;i++) { ((float*)A)[i]=((i*2654435761u)>>13&0x3fff)*1e-6f; }
  printf("=== transposed-A cp.async sweep, N=%d ===\n",N);
  #define T(bm,bn,bk,th,st){double t=runTA<bm,bn,bk,th,st>(A,B,C,N,IT); \
    printf("BM=%d BN=%d BK=%d thr=%d st=%d: %.2f TFLOP/s\n",bm,bn,bk,th,st,t);fflush(stdout);}
  T(128,128,8,256,3) T(128,128,8,256,4) T(128,128,8,256,6)
  T(128,128,16,256,2) T(128,128,16,256,3) T(128,128,16,256,4)
  T(128,128,32,256,2) T(128,128,32,256,3)
  T(128,128,16,512,2) T(128,128,16,512,3)
  T(64,64,16,128,3) T(64,128,8,256,4)
  return 0;
}
EOF
