// In-process head-to-head config sweep vs cuBLAS on A40.
// Transposed-A float4 kernel, parameterized by block tile, register tile
// (RR=thread rows, RC=thread cols), BK, STAGES, THREADS, WARP tile dims.
#include <cuda_runtime.h>
#include <cuda_pipeline.h>
#include <cublas_v2.h>
#include <cstdio>
#include <cstdlib>

// WARP tile is ROWS x COLS in register-elements. THREADS = (BM/ROWS)*(BN/COLS).
// Each thread owns RR=ROWS? We instead param RR,RC directly.
template <int BM,int BN,int BK,int THREADS,int STAGES,int RR,int RC,int WTR,int WTC>
__global__ void __launch_bounds__(THREADS)
k(const float* A,const float* B,float* C,int N){
  extern __shared__ float smem[];
  float(*As)[BK][BM]=reinterpret_cast<float(*)[BK][BM]>(smem);
  float(*Bs)[BK][BN]=reinterpret_cast<float(*)[BK][BN]>(smem+STAGES*BK*BM);
  const int tid=threadIdx.x, warp=tid>>5, lane=tid&31;
  // thread grid inside warp: WTC cols x WTR rows of RC-wide, RR-tall sub-tiles
  const int ty=lane/WTC, tx=lane%WTC;      // WTC*WTR=32
  const int warpR=warp/(BN/RC/WTC);        // warps along rows
  const int warpC=warp%(BN/RC/WTC);
  const int rLo=warpR*WTR*RR + ty*RR;
  const int cLo=warpC*WTC*RC + tx*RC;
  const int row0=blockIdx.y*BM, col0=blockIdx.x*BN; const int nKT=(N+BK-1)/BK;

  float acc[RR][RC];
#pragma unroll
  for(int i=0;i<RR;i++)
#pragma unroll
    for(int j=0;j<RC;j++) acc[i][j]=0.f;

  auto loadA=[&](int k0,int slot){
#pragma unroll
    for(int i=0;i<(BM*BK/4+THREADS-1)/THREADS;i++){
      int idx=tid+i*THREADS; if(idx>=BM*BK/4)continue;
      int r=idx/(BK/4),kf=idx%(BK/4); int gr=row0+r,gc=k0+kf*4; float4 v;
      if(gr<N&&gc+3<N) v=*reinterpret_cast<const float4*>(&A[gr*N+gc]);
      else{v.x=gr<N&&gc<N?A[gr*N+gc]:0.f;v.y=gr<N&&gc+1<N?A[gr*N+gc+1]:0.f;v.z=gr<N&&gc+2<N?A[gr*N+gc+2]:0.f;v.w=gr<N&&gc+3<N?A[gr*N+gc+3]:0.f;}
      As[slot][kf*4+0][r]=v.x;As[slot][kf*4+1][r]=v.y;As[slot][kf*4+2][r]=v.z;As[slot][kf*4+3][r]=v.w; }
  };
  auto loadB=[&](int k0,int slot){
#pragma unroll
    for(int i=0;i<(BK*BN/4+THREADS-1)/THREADS;i++){
      int idx=tid+i*THREADS; if(idx>=BK*BN/4)continue;
      int k=idx/(BN/4),cf=idx%(BN/4); int gr=k0+k,gc=col0+cf*4;
      if(gr<N&&gc+3<N) __pipeline_memcpy_async(&Bs[slot][k][cf*4],&B[gr*N+gc],16);
      else{Bs[slot][k][cf*4]=gr<N&&gc<N?B[gr*N+gc]:0.f;Bs[slot][k][cf*4+1]=gr<N&&gc+1<N?B[gr*N+gc+1]:0.f;Bs[slot][k][cf*4+2]=gr<N&&gc+2<N?B[gr*N+gc+2]:0.f;Bs[slot][k][cf*4+3]=gr<N&&gc+3<N?B[gr*N+gc+3]:0.f;}
    }
  };
  int issued=0;
  while(issued<nKT&&issued<STAGES-1){loadA(issued*BK,issued%STAGES);loadB(issued*BK,issued%STAGES);__pipeline_commit();issued++;}
  for(int t=0;t<nKT;t++){
    __pipeline_wait_prior((issued-1)-t); __syncthreads();
    if(issued<nKT){loadA(issued*BK,issued%STAGES);loadB(issued*BK,issued%STAGES);__pipeline_commit();issued++;}
    int slot=t%STAGES;
#pragma unroll
    for(int k=0;k<BK;k++){
      // A: RR rows contiguous -> read as ceil(RR/4) float4s
      float av[RR];
      #pragma unroll
      for(int p=0;p<(RR+3)/4;p++){
        float4 q=*reinterpret_cast<const float4*>(&As[slot][k][rLo+p*4]);
        av[p*4+0]=q.x;av[p*4+1]=q.y;av[p*4+2]=q.z;av[p*4+3]=q.w;
      }
      // B: RC cols contiguous -> RC/4 float4s
      float bv[RC];
      #pragma unroll
      for(int p=0;p<RC/4;p++){
        float4 q=*reinterpret_cast<const float4*>(&Bs[slot][k][cLo+p*4]);
        bv[p*4+0]=q.x;bv[p*4+1]=q.y;bv[p*4+2]=q.z;bv[p*4+3]=q.w;
      }
#pragma unroll
      for(int i=0;i<RR;i++)
#pragma unroll
        for(int j=0;j<RC;j++) acc[i][j]+=av[i]*bv[j];
    }
    __syncthreads();
  }
  int gR0=row0+rLo,gC0=col0+cLo;
#pragma unroll
  for(int i=0;i<RR;i++){int r=gR0+i;if(r>=N)continue;
#pragma unroll
    for(int j=0;j<RC;j++){int c=gC0+j;if(c<N)C[r*N+c]=acc[i][j];}}
}

template <int BM,int BN,int BK,int THREADS,int STAGES,int RR,int RC,int WTR,int WTC>
double runT(const float*A,const float*B,float*C,int N,int it){
  size_t sh=((size_t)STAGES*BK*BM+(size_t)STAGES*BK*BN)*4;
  dim3 block(THREADS),grid((N+BM-1)/BM,(N+BN-1)/BN);
  cudaFuncSetAttribute(k<BM,BN,BK,THREADS,STAGES,RR,RC,WTR,WTC>,cudaFuncAttributeMaxDynamicSharedMemorySize,(int)sh);
  for(int i=0;i<6;i++)k<BM,BN,BK,THREADS,STAGES,RR,RC,WTR,WTC><<<grid,block,sh>>>(A,B,C,N);
  cudaDeviceSynchronize();
  cudaError_t e=cudaGetLastError(); if(e!=cudaSuccess){printf("FAIL %s\n",cudaGetErrorString(e));return -1;}
  cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
  cudaEventRecord(a);for(int i=0;i<it;i++)k<BM,BN,BK,THREADS,STAGES,RR,RC,WTR,WTC><<<grid,block,sh>>>(A,B,C,N);cudaEventRecord(b);
  cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);
  return 2.0*N*N*N*it/(ms/1e3)/1e12;
}

template <int BM,int BN,int BK,int THREADS,int STAGES,int RR,int RC,int WTR,int WTC>
void sweepOne(cublasHandle_t h,const float*A,const float*B,float*C,int N,int it){
  double m=runT<BM,BN,BK,THREADS,STAGES,RR,RC,WTR,WTC>(A,B,C,N,it);
  float a=1.f,b=0.f; int reps=3; double cb=0;
  cudaEvent_t x,y;cudaEventCreate(&x);cudaEventCreate(&y);
  cudaEventRecord(x);for(int r=0;r<reps;r++)cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&a,A,N,B,N,&b,C,N);cudaEventRecord(y);
  cudaEventSynchronize(y);float ms;cudaEventElapsedTime(&ms,x,y);
  cb=2.0*N*N*N*reps/(ms/1e3)/1e12;
  printf("%dx%d BK%d st%d thr%d RRxRC=%dx%d warp%dx%d: %.2f  cuBLAS=%.2f ratio=%.3f\n",
    BM,BN,BK,STAGES,THREADS,RR,RC,WTR,WTC,m,cb,m/cb);fflush(stdout);
}

int main(int ac,char**av){
  int N=ac>1?atoi(av[1]):4096; size_t by=(size_t)N*N*4; int IT=15;
  float*A,*B,*C;cudaMalloc(&A,by);cudaMalloc(&B,by);cudaMalloc(&C,by);
  cublasHandle_t h;cublasCreate(&h);
  float a=1.f,b=0.f;
  for(int i=0;i<3;i++)cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&a,A,N,B,N,&b,C,N);
  cudaDeviceSynchronize(); // warm cublas heuristics
  printf("=== in-process sweep vs cuBLAS, N=%d ===\n",N);
  // 8x8 variants
  sweepOne<128,128,8,256,4,8,8,8,4>(h,A,B,C,N,IT);
  sweepOne<128,128,8,256,3,8,8,8,4>(h,A,B,C,N,IT);
  sweepOne<128,128,16,256,3,8,8,8,4>(h,A,B,C,N,IT);
  sweepOne<128,128,16,256,4,8,8,8,4>(h,A,B,C,N,IT);
  // 4x8 register tile (fewer acc regs -> more blocks possible)
  sweepOne<128,128,8,256,4,4,8,4,8>(h,A,B,C,N,IT);
  sweepOne<128,128,8,256,6,4,8,4,8>(h,A,B,C,N,IT);
  sweepOne<128,128,16,256,4,4,8,4,8>(h,A,B,C,N,IT);
  // 8x16 register tile
  sweepOne<128,128,8,128,4,8,16,8,2>(h,A,B,C,N,IT);
  // 256x128 block, 8x8
  sweepOne<256,128,8,256,4,8,8,8,4>(h,A,B,C,N,IT);
  sweepOne<128,256,8,256,4,8,8,8,4>(h,A,B,C,N,IT);
  return 0;
}

