// returns -1 on error / invalid, else TFLOP/s
template <int BM,int BN,int BK,int THREADS,int STAGES,int RR,int RC,int WTR,int WTC>
double runT(const float*A,const float*B,float*C,float*REF,const float*hREF,float*hOUT,int N,int it,const char*name){
  size_t sh=((size_t)STAGES*BK*BM+(size_t)STAGES*BK*BN)*4;
  dim3 block(THREADS),grid((N+BM-1)/BM,(N+BN-1)/BN);
  cudaFuncSetAttribute(k<BM,BN,BK,THREADS,STAGES,RR,RC,WTR,WTC>,cudaFuncAttributeMaxDynamicSharedMemorySize,(int)sh);
  for(int i=0;i<6;i++)k<BM,BN,BK,THREADS,STAGES,RR,RC,WTR,WTC><<<grid,block,sh>>>(A,B,C,N);
  cudaDeviceSynchronize();
  cudaError_t e=cudaGetLastError(); if(e!=cudaSuccess){printf("%-40s LAUNCH FAIL %s\n",name,cudaGetErrorString(e));return -1;}
  // validate
  cudaMemcpy(hOUT,C,(size_t)N*N*4,cudaMemcpyDeviceToHost);
  double err=0,worst=1e30;
  for(size_t i=0;i<(size_t)N*N;i++){double d=(double)hOUT[i]-hREF[i]; err+=d*d;}
  err/=(double)N*N;
  cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
  cudaEventRecord(a);for(int i=0;i<it;i++)k<BM,BN,BK,THREADS,STAGES,RR,RC,WTR,WTC><<<grid,block,sh>>>(A,B,C,N);cudaEventRecord(b);
  cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);
  double t=2.0*N*N*N*it/(ms/1e3)/1e12;
  printf("%-40s %.2f TFLOP/s  (MSE vs cublas %.2e) %s\n",name,t,err, err<1e-4?"OK":"**INCORRECT**");fflush(stdout);
  return err<1e-4?t:-1;
}

template <int BM,int BN,int BK,int THREADS,int STAGES,int RR,int RC,int WTR,int WTC>
void S(cublasHandle_t h,const float*A,const float*B,float*C,float*REF,const float*hREF,float*hOUT,int N,int it,const char*name){
  double m=runT<BM,BN,BK,THREADS,STAGES,RR,RC,WTR,WTC>(A,B,C,REF,hREF,hOUT,N,it,name);
  if(m<0)return;
  float a=1.f,b=0.f;int reps=3;
  cudaEvent_t x,y;cudaEventCreate(&x);cudaEventCreate(&y);
  cudaEventRecord(x);for(int r=0;r<reps;r++)cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&a,A,N,B,N,&b,C,N);cudaEventRecord(y);
  cudaEventSynchronize(y);float ms;cudaEventElapsedTime(&ms,x,y);
  double cb=2.0*N*N*N*reps/(ms/1e3)/1e12;
  printf("%-40s wrt cuBLAS(%.2f): ratio=%.3f\n"," ",cb,m/cb);
}

int main(int ac,char**av){
  int N=ac>1?atoi(av[1]):4096; size_t by=(size_t)N*N*4; int IT=15;
  float*A,*B,*C,*REF;cudaMalloc(&A,by);cudaMalloc(&B,by);cudaMalloc(&C,by);cudaMalloc(&REF,by);
