// Careful block-size sweep: every candidate validated against CPU reference
// at multiple N (incl. ragged). Threads derived = BM*BN/(RR*RC).
#include <cuda_runtime.h>
#include <cuda_pipeline.h>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <random>

template <int BM,int BN,int BK,int STAGES,int THREADS>
__global__ void __launch_bounds__(THREADS)
kT(const float* A,const float* B,float* C,int N){
  extern __shared__ float smem[];
  float(*As)[BK][BM]=reinterpret_cast<float(*)[BK][BM]>(smem);
  float(*Bs)[BK][BN]=reinterpret_cast<float(*)[BK][BN]>(smem+STAGES*BK*BM);
  const int tid=threadIdx.x, warp=tid>>5, lane=tid&31;
  const int ty=lane>>2, tx=lane&3;          // 8x4 within warp
  const int warpsX=BN/32;                    // warps across columns (each 32 wide)
  const int rowsPerBlockWarps=THREADS/32/warpsX;
  const int warpR=warp/warpsX, warpC=warp%warpsX;
  const int rLo=warpR*64 + ty*8;             // warp covers 64 rows
  const int cLo=warpC*32 + tx*8;             // warp covers 32 cols
  const int row0=blockIdx.y*BM, col0=blockIdx.x*BN; const int nKT=(N+BK-1)/BK;
  float acc[8][8];
#pragma unroll
  for(int i=0;i<8;i++)
#pragma unroll
    for(int j=0;j<8;j++) acc[i][j]=0.f;
  auto loadA=[&](int k0,int slot){
#pragma unroll
    for(int i=0;i<(BM*BK/4+THREADS-1)/THREADS;i++){
      int idx=tid+i*THREADS; if(idx>=BM*BK/4)continue;
      int r=idx/(BK/4),kf=idx%(BK/4); int gr=row0+r,gc=k0+kf*4; float4 v;
      if(gr<N&&gc+3<N) v=*reinterpret_cast<const float4*>(&A[gr*N+gc]);
      else{v.x=gr<N&&gc<N?A[gr*N+gc]:0.f;v.y=gr<N&&gc+1<N?A[gr*N+gc+1]:0.f;v.z=gr<N&&gc+2<N?A[gr*N+gc+2]:0.f;v.w=gr<N&&gc+3<N?A[gr*N+gc+3]:0.f;}
      As[slot][kf*4+0][r]=v.x;As[slot][kf*4+1][r]=v.y;As[slot][kf*4+2][r]=v.z;As[slot][kf*4+3][r]=v.w; }
  };
  auto loadB=[&](int k0,int slot){
#pragma unroll
    for(int i=0;i<(BK*BN/4+THREADS-1)/THREADS;i++){
      int idx=tid+i*THREADS; if(idx>=BK*BN/4)continue;
      int k=idx/(BN/4),cf=idx%(BN/4); int gr=k0+k,gc=col0+cf*4;
      if(gr<N&&gc+3<N) __pipeline_memcpy_async(&Bs[slot][k][cf*4],&B[gr*N+gc],16);
      else{Bs[slot][k][cf*4]=gr<N&&gc<N?B[gr*N+gc]:0.f;Bs[slot][k][cf*4+1]=gr<N&&gc+1<N?B[gr*N+gc+1]:0.f;Bs[slot][k][cf*4+2]=gr<N&&gc+2<N?B[gr*N+gc+2]:0.f;Bs[slot][k][cf*4+3]=gr<N&&gc+3<N?B[gr*N+gc+3]:0.f;}
    }
  };
  int issued=0;
  while(issued<nKT&&issued<STAGES-1){loadA(issued*BK,issued%STAGES);loadB(issued*BK,issued%STAGES);__pipeline_commit();issued++;}
  for(int t=0;t<nKT;t++){
    __pipeline_wait_prior((issued-1)-t); __syncthreads();
    if(issued<nKT){loadA(issued*BK,issued%STAGES);loadB(issued*BK,issued%STAGES);__pipeline_commit();issued++;}
    int slot=t%STAGES;
#pragma unroll
    for(int k=0;k<BK;k++){
      float4 a0=*reinterpret_cast<const float4*>(&As[slot][k][rLo]);
      float4 a1=*reinterpret_cast<const float4*>(&As[slot][k][rLo+4]);
      float4 b0=*reinterpret_cast<const float4*>(&Bs[slot][k][cLo]);
      float4 b1=*reinterpret_cast<const float4*>(&Bs[slot][k][cLo+4]);
      float av[8]={a0.x,a0.y,a0.z,a0.w,a1.x,a1.y,a1.z,a1.w};
      float bv[8]={b0.x,b0.y,b0.z,b0.w,b1.x,b1.y,b1.z,b1.w};
#pragma unroll
      for(int i=0;i<8;i++)
#pragma unroll
        for(int j=0;j<8;j++) acc[i][j]+=av[i]*bv[j];
    }
    __syncthreads();
  }
  int gR0=row0+rLo,gC0=col0+cLo;
#pragma unroll
  for(int i=0;i<8;i++){int r=gR0+i;if(r>=N)continue;
#pragma unroll
    for(int j=0;j<8;j++){int c=gC0+j;if(c<N)C[r*N+c]=acc[i][j];}}
}

static std::vector<float> A_h,B_h;
static float *A,*B,*C;
static int NN;
static double cpuRef(int i,int j){
  double s=0; for(int k=0;k<NN;k++) s+=(double)A_h[i*NN+k]*B_h[k*NN+j]; return s;
}

// validate candidate vs CPU for sampled entries + return perf
template <int BM,int BN,int BK,int STAGES,int THREADS>
void testK(int N,int it){
  NN=N;
  size_t by=(size_t)N*N*4;
  size_t sh=((size_t)STAGES*BK*BM+(size_t)STAGES*BK*BN)*4;
  dim3 block(THREADS),grid((N+BM-1)/BM,(N+BN-1)/BN);
  cudaFuncSetAttribute(kT<BM,BN,BK,STAGES,THREADS>,cudaFuncAttributeMaxDynamicSharedMemorySize,(int)sh);
  // correctness: copy C out and compare CPU
  cudaMemset(C,0,by);
  kT<BM,BN,BK,STAGES,THREADS><<<grid,block,sh>>>(A,B,C,N);
  cudaError_t e=cudaGetLastError();
  if(e!=cudaSuccess){printf("[%dx%d BK%d st%d thr%d] LAUNCH FAIL %s\n",BM,BN,BK,STAGES,THREADS,cudaGetErrorString(e));return;}
  cudaDeviceSynchronize();
  std::vector<float> hC(N*N); cudaMemcpy(hC.data(),C,by,cudaMemcpyDeviceToHost);
  double err=0,cnt=0; size_t stride=1+N/16;
  for(size_t i=0;i<(size_t)N;i+=1+ N/32)
    for(size_t j=0;j<(size_t)N;j+=1+ N/32){ double d=(double)hC[i*N+j]-cpuRef(i,j); err+=d*d; cnt++; }
  err/=(cnt?cnt:1);
  bool ok=err<1e-4;
  // timing
  kT<BM,BN,BK,STAGES,THREADS><<<grid,block,sh>>>(A,B,C,N);cudaDeviceSynchronize();
  cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
  cudaEventRecord(a);for(int i=0;i<it;i++)kT<BM,BN,BK,STAGES,THREADS><<<grid,block,sh>>>(A,B,C,N);cudaEventRecord(b);
  cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);
  double t=2.0*N*N*N*it/(ms/1e3)/1e12;
  printf("[%3dx%-3d BK%-2d st%d thr%-4d] %6.2f TFLOP/s  CPU-MSE=%.2e %s\n",
    BM,BN,BK,STAGES,THREADS,t,err,ok?"OK":"**BAD**");fflush(stdout);
}

int main(int ac,char**av){
  int N=ac>1?atoi(av[1]):4096; int IT=15;
  NN=N; size_t by=(size_t)N*N*4;
  A_h.resize(N*N);B_h.resize(N*N);
  std::mt19937 rng(7); std::uniform_real_distribution<float> d(-1,1);
  for(auto&x:A_h)x=d(rng); for(auto&x:B_h)x=d(rng);
  cudaMalloc(&A,by);cudaMalloc(&B,by);cudaMalloc(&C,by);
  cudaMemcpy(A,A_h.data(),by,cudaMemcpyHostToDevice);cudaMemcpy(B,B_h.data(),by,cudaMemcpyHostToDevice);
  printf("=== correct-thread block-size sweep, N=%d (validated vs CPU) ===\n",N);
  // threads = BM*BN/64
  testK<128,128,8,4,256>(N,IT);
  testK<128,256,8,4,512>(N,IT);
  testK<256,128,8,4,512>(N,IT);
  testK<256,256,8,3,1024>(N,IT);
  testK<256,256,8,4,1024>(N,IT);
  testK<256,256,16,2,1024>(N,IT);
  testK<256,128,16,3,512>(N,IT);
  testK<128,256,16,3,512>(N,IT);
  testK<128,128,8,3,256>(N,IT);
  testK<128,384,8,3,512>(N,IT);
  return 0;
}

