#include <cuda_runtime.h>
#include <cuda_pipeline.h>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <random>

template <int BM,int BN,int BK,int STAGES,int THREADS>
__global__ void __launch_bounds__(THREADS)
kT(const float* A,const float* B,float* C,int N){
  extern __shared__ float smem[];
  float(*As)[BK][BM]=reinterpret_cast<float(*)[BK][BM]>(smem);
  float(*Bs)[BK][BN]=reinterpret_cast<float(*)[BK][BN]>(smem+STAGES*BK*BM);
  const int tid=threadIdx.x, warp=tid>>5, lane=tid&31;
  const int ty=lane>>2, tx=lane&3;
  const int warpsX=BN/32;
  const int rowsPerBlockWarps=THREADS/32/warpsX;
  const int warpR=warp/warpsX, warpC=warp%warpsX;
  const int rLo=warpR*64+ty*8, cLo=warpC*32+tx*8;
  const int row0=blockIdx.y*BM, col0=blockIdx.x*BN; const int nKT=(N+BK-1)/BK;
  float acc[8][8];
#pragma unroll
  for(int i=0;i<8;i++)
#pragma unroll
    for(int j=0;j<8;j++) acc[i][j]=0.f;
  auto loadA=[&](int k0,int slot){
#pragma unroll
    for(int i=0;i<(BM*BK/4+THREADS-1)/THREADS;i++){
      int idx=tid+i*THREADS; if(idx>=BM*BK/4)continue;
      int r=idx/(BK/4),kf=idx%(BK/4); int gr=row0+r,gc=k0+kf*4; float4 v;
      if(gr<N&&gc+3<N) v=*reinterpret_cast<const float4*>(&A[gr*N+gc]);
      else{v.x=gr<N&&gc<N?A[gr*N+gc]:0.f;v.y=gr<N&&gc+1<N?A[gr*N+gc+1]:0.f;v.z=gr<N&&gc+2<N?A[gr*N+gc+2]:0.f;v.w=gr<N&&gc+3<N?A[gr*N+gc+3]:0.f;}
      As[slot][kf*4+0][r]=v.x;As[slot][kf*4+1][r]=v.y;As[slot][kf*4+2][r]=v.z;As[slot][kf*4+3][r]=v.w; }
  };
  auto loadB=[&](int k0,int slot){
#pragma unroll
    for(int i=0;i<(BK*BN/4+THREADS-1)/THREADS;i++){
      int idx=tid+i*THREADS; if(idx>=BK*BN/4)continue;
      int k=idx/(BN/4),cf=idx%(BN/4); int gr=k0+k,gc=col0+cf*4;
      if(gr<N&&gc+3<N) __pipeline_memcpy_async(&Bs[slot][k][cf*4],&B[gr*N+gc],16);
      else{Bs[slot][k][cf*4]=gr<N&&gc<N?B[gr*N+gc]:0.f;Bs[slot][k][cf*4+1]=gr<N&&gc+1<N?B[gr*N+gc+1]:0.f;Bs[slot][k][cf*4+2]=gr<N&&gc+2<N?B[gr*N+gc+2]:0.f;Bs[slot][k][cf*4+3]=gr<N&&gc+3<N?B[gr*N+gc+3]:0.f;}
