#pragma unroll
    for(int j=0;j<8;j++){int c=gC0+j;if(c<N)C[r*N+c]=acc[i][j];}}
}

template <int BM,int BN,int BK,int STAGES,int THREADS>
double bench(const float*A,const float*B,float*C,int N,int reps){
  size_t sh=((size_t)STAGES*BK*BM+(size_t)STAGES*BK*BN)*4;
  dim3 block(THREADS),grid((N+BN-1)/BN,(N+BM-1)/BM);
  cudaFuncSetAttribute(kT<BM,BN,BK,STAGES,THREADS>,cudaFuncAttributeMaxDynamicSharedMemorySize,(int)sh);
  for(int i=0;i<4;i++)kT<BM,BN,BK,STAGES,THREADS><<<grid,block,sh>>>(A,B,C,N);
  cudaDeviceSynchronize();
  double best=1e18;
  for(int r=0;r<reps;r++){
    cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
    cudaEventRecord(a);for(int i=0;i<8;i++)kT<BM,BN,BK,STAGES,THREADS><<<grid,block,sh>>>(A,B,C,N);cudaEventRecord(b);
    cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);
    double t=2.0*N*N*N*8/(ms/1e3)/1e12;
    if(t<best)best=t;
  }
  return best;
}

#define B0(bm,bn,bk,st,th,nm) {double t=bench<bm,bn,bk,st,th>(A,B,C,N,reps); printf("%-28s best %.2f TFLOP/s\n",nm,t);fflush(stdout);}

int main(int ac,char**av){
  int N=ac>1?atoi(av[1]):4096; int reps=ac>2?atoi(av[2]):8;
  size_t by=(size_t)N*N*4;
  std::vector<float> A_h(N*N),B_h(N*N); std::mt19937 r(7); std::uniform_real_distribution<float>d(-1,1);
  for(auto&x:A_h)x=d(r);for(auto&x:B_h)x=d(r);
  float*A,*B,*C;cudaMalloc(&A,by);cudaMalloc(&B,by);cudaMalloc(&C,by);
  cudaMemcpy(A,A_h.data(),by,cudaMemcpyHostToDevice);cudaMemcpy(B,B_h.data(),by,cudaMemcpyHostToDevice);
  printf("=== interleaved best-of-%d, N=%d ===\n",reps,N);
  B0(128,128,8,3,256,"128x128 BK8 st3");
  B0(128,128,8,4,256,"128x128 BK8 st4");
  B0(128,128,16,3,256,"128x128 BK16 st3");
  B0(128,128,16,4,256,"128x128 BK16 st4");
  B0(128,256,16,3,512,"128x256 BK16 st3");
  B0(128,256,8,4,512,"128x256 BK8 st4");
  B0(256,128,16,3,512,"256x128 BK16 st3");
  B0(256,128,8,4,512,"256x128 BK8 st4");
  B0(256,256,16,2,1024,"256x256 BK16 st2");
  B0(256,128,16,4,512,"256x128 BK16 st4");
  return 0;
}

