  for(int t=0;t<nKT;t++){
    __pipeline_wait_prior((issued-1)-t); __syncthreads();
    if(issued<nKT){loadA(issued*BK,issued%STAGES);loadB(issued*BK,issued%STAGES);__pipeline_commit();issued++;}
    int slot=t%STAGES;
#pragma unroll
    for(int k=0;k<BK;k++){
      float4 a0=*reinterpret_cast<const float4*>(&As[slot][k][rLo]);
      float4 a1=*reinterpret_cast<const float4*>(&As[slot][k][rLo+4]);
      float4 b0=*reinterpret_cast<const float4*>(&Bs[slot][k][cLo]);
      float4 b1=*reinterpret_cast<const float4*>(&Bs[slot][k][cLo+4]);
      float av[8]={a0.x,a0.y,a0.z,a0.w,a1.x,a1.y,a1.z,a1.w};
      float bv[8]={b0.x,b0.y,b0.z,b0.w,b1.x,b1.y,b1.z,b1.w};
#pragma unroll
      for(int i=0;i<8;i++)
#pragma unroll
        for(int j=0;j<8;j++) acc[i][j]+=av[i]*bv[j];
    }
    __syncthreads();
  }
  int gR0=row0+rLo,gC0=col0+cLo;
#pragma unroll
  for(int i=0;i<8;i++){int r=gR0+i;if(r>=N)continue;
#pragma unroll
    for(int j=0;j<8;j++){int c=gC0+j;if(c<N)C[r*N+c]=acc[i][j];}}
}

template <int BM,int BN,int BK,int STAGES,int THREADS>
double timeK(const float*A,const float*B,float*C,int N,int it){
  size_t sh=((size_t)STAGES*BK*BM+(size_t)STAGES*BK*BN)*4;
  dim3 block(THREADS),grid((N+BN-1)/BN,(N+BM-1)/BM);
  cudaFuncSetAttribute(kT<BM,BN,BK,STAGES,THREADS>,cudaFuncAttributeMaxDynamicSharedMemorySize,(int)sh);
  kT<BM,BN,BK,STAGES,THREADS><<<grid,block,sh>>>(A,B,C,N);cudaDeviceSynchronize();
  cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
  cudaEventRecord(a);for(int i=0;i<it;i++)kT<BM,BN,BK,STAGES,THREADS><<<grid,block,sh>>>(A,B,C,N);cudaEventRecord(b);
  cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);
  return 2.0*N*N*N*it/(ms/1e3)/1e12;
}
double timeC(cublasHandle_t h,const float*A,const float*B,float*C,int N,int it){
  float a=1.f,b=0.f;
  cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&a,A,N,B,N,&b,C,N);cudaDeviceSynchronize();
