    printf("  %-22s rep%d  MINE=%.2f cuBLAS=%.2f ratio=%.2f\n",name,rep,m,c,m/c);
  }
  printf("  ---\n");fflush(stdout);
}

int main(int ac,char**av){
  int N=ac>1?atoi(av[1]):4096; int it=ac>2?atoi(av[2]):10;
  size_t by=(size_t)N*N*4;
  std::vector<float> A_h(N*N),B_h(N*N); std::mt19937 r(7); std::uniform_real_distribution<float>d(-1,1);
  for(auto&x:A_h)x=d(r);for(auto&x:B_h)x=d(r);
  float*A,*B,*C;cudaMalloc(&A,by);cudaMalloc(&B,by);cudaMalloc(&C,by);
  cudaMemcpy(A,A_h.data(),by,cudaMemcpyHostToDevice);cudaMemcpy(B,B_h.data(),by,cudaMemcpyHostToDevice);
  cublasHandle_t h;cublasCreate(&h);
  float a=1.f,b=0.f; for(int i=0;i<3;i++)cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&a,A,N,B,N,&b,C,N);
